  KEY `fk_pay_user` (`entered_by`),
  KEY `idx_pay_batch` (`import_batch_id`),
  CONSTRAINT `fk_pay_batch` FOREIGN KEY (`import_batch_id`) REFERENCES `import_batches` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
